> > +		p->scx.reject_reason = SCX_TASK_REENQ_NONE;
> > +
> > +		if (WARN_ON_ONCE(p->scx.flags & SCX_TASK_REENQ_REASON_MASK))
> > +			p->scx.flags &= ~SCX_TASK_REENQ_REASON_MASK;
> > +		p->scx.flags |= reason;
