+		ntb_mw_clear_trans_group(nt->ndev, PIDX, first);
+	else
+		ntb_mw_clear_trans(nt->ndev, PIDX, first);
+
+	alloc_addr = mw->alloc_addr;
+	alloc_size = mw->alloc_size;
+	original_dma_addr = mw->original_dma_addr;
+	for (i = first; i < first + count; i++) {
